# 1. 数据类型诊断
cat("=== 因变量BATH2诊断 ===\n")
cat("变量类型:", ifelse(all(londonhp$BATH2 %in% 0:1), "二元变量", "计数变量"), "\n")
cat("取值分布:\n")
print(table(londonhp$BATH2))

# 2. 分布族选择流程
cat("\n=== 分布族选择流程 ===\n")
if(max(londonhp$BATH2) > 1) {
  cat("1. 因变量为计数数据 → 选择泊松分布\n")
  cat("2. 检查过度离散:")

  # 过度离散检验
  mean.val <- mean(londonhp$BATH2)
  var.val <- var(londonhp$BATH2)
  cat(" 均值 =", mean.val, " 方差 =", var.val, "\n")

  if(var.val > 1.5 * mean.val) {
    cat("3. 存在过度离散 → 考虑负二项分布\n")
    cat("   当前示例未演示负二项GGWR实现\n")
  } else {
    cat("3. 无显著过度离散 → 使用泊松分布\n")
  }
} else {
  cat("1. 因变量为二元数据 → 选择二项分布\n")
}

# 3. 模型实现代码
cat("\n=== 推荐实现代码 ===\n")
if(max(londonhp$BATH2) > 1) {
  cat("# 泊松GGWR实现\n")
  cat("bw.pois <- bw.ggwr(BATH2 ~ FLOORSZ, data = londonhp, dMat = DM)\n")
  cat("res.pois <- ggwr.basic(BATH2 ~ FLOORSZ, bw = bw.pois, data = londonhp, dMat = DM)\n")
} else {
  cat("# 二项GGWR实现\n")
  cat("bw.bin <- bw.ggwr(BATH2 ~ FLOORSZ, data = londonhp, dMat = DM, family = "binomial")\n")
  cat("res.bin <- ggwr.basic(BATH2 ~ FLOORSZ, bw = bw.bin, data = londonhp, dMat = DM, family = "binomial")\n")
}

# 4. 验证建议
